function drawChart(){const c=$('#priceChart');if(!c||!chartData.length)return;const rect=c.getBoundingClientRect(),w=rect.width,h=rect.height;if(w<1||h<1)return;const dpr=devicePixelRatio||1;c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);const ctx=c.getContext('2d');ctx.scale(dpr,dpr);const data=chartData.slice(-chartPoints),factor=chartMetric==='cap'?1e9:1,min=Math.min(...data.map(d=>d.low))*.985,max=Math.max(...data.map(d=>d.high))*1.015;const left=12,right=w-88,top=22,bottom=h-83,step=(right-left)/data.length,y=v=>bottom-(v-min)/(max-min)*(bottom-top),x=i=>left+(i+.5)*step,price=v=>chartMetric==='cap'?fmt(v*factor):v.toFixed(7);ctx.clearRect(0,0,w,h);ctx.font='11px "Pixelify Sans", monospace';ctx.strokeStyle='#1a2639';ctx.fillStyle='#697d9b';ctx.lineWidth=1;for(let i=0;i<=5;i++){let yy=top+(bottom-top)*i/5;ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(right,yy);ctx.stroke();ctx.fillText(price(max-(max-min)*i/5),right+10,yy+4)}const vmax=Math.max(...data.map(d=>d.volume));data.forEach((d,i)=>{const up=d.close>=d.open;ctx.fillStyle=up?'#3f88ff55':'#e38aab55';ctx.fillRect(x(i)-step*.3,h-30-d.volume/vmax*38,Math.max(1,step*.6),d.volume/vmax*38);if(chartStyle==='candles'){ctx.strokeStyle=ctx.fillStyle=up?'#639dff':'#de8ca7';ctx.beginPath();ctx.moveTo(x(i),y(d.high));ctx.lineTo(x(i),y(d.low));ctx.stroke();ctx.fillRect(x(i)-step*.3,Math.min(y(d.open),y(d.close)),Math.max(1,step*.6),Math.max(1,Math.abs(y(d.open)-y(d.close))))}});if(chartStyle==='line'){const grad=ctx.createLinearGradient(0,top,0,bottom);grad.addColorStop(0,'#347cff55');grad.addColorStop(1,'#347cff00');ctx.beginPath();data.forEach((d,i)=>i?ctx.lineTo(x(i),y(d.close)):ctx.moveTo(x(i),y(d.close)));ctx.lineTo(x(data.length-1),bottom);ctx.lineTo(x(0),bottom);ctx.closePath();ctx.fillStyle=grad;ctx.fill();ctx.beginPath();data.forEach((d,i)=>i?ctx.lineTo(x(i),y(d.close)):ctx.moveTo(x(i),y(d.close)));ctx.strokeStyle='#6aa7ff';ctx.lineWidth=2;ctx.stroke()}
ctx.fillStyle='#7185a3';for(let i=0;i<data.length;i+=Math.ceil(data.length/5)){const dt=new Date(data[i].time);ctx.fillText(chartInterval>=240?dt.toISOString().slice(5,10):dt.toISOString().slice(11,16),x(i)-15,h-9)}const last=data.at(-1);ctx.setLineDash([4,4]);ctx.strokeStyle='#5597ff88';ctx.beginPath();ctx.moveTo(left,y(last.close));ctx.lineTo(right,y(last.close));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#2e70e3';ctx.fillRect(right+3,y(last.close)-9,82,18);ctx.fillStyle='white';ctx.fillText(price(last.close),right+7,y(last.close)+4);let index=chartHover>=0?Math.min(data.length-1,chartHover):data.length-1;const d=data[index];if(chartHover>=0){ctx.setLineDash([3,4]);ctx.strokeStyle='#bbd2f4aa';ctx.beginPath();ctx.moveTo(x(index),top);ctx.lineTo(x(index),h-28);ctx.moveTo(left,y(d.close));ctx.lineTo(right,y(d.close));ctx.stroke();ctx.setLineDash([])}$('#ohlc').innerHTML=`<span>${new Date(d.time).toISOString().slice(5,16).replace('T',' ')} UTC</span> <span>O <b>${price(d.open)}</b></span> <span>H <b>${price(d.high)}</b></span> <span>L <b>${price(d.low)}</b></span> <span>C <b>${price(d.close)}</b></span>`}
function activity(tab){const t=selected;if(tab==='about'){$('#activityContent').innerHTML=`<div class="about-content"><h3>About ${esc(t.name)}</h3><p>${esc(t.desc)}</p><div class="info-box">${t.status==='draft'?'This token is a device-local draft. It has not been minted.':'This is a fictional sample market. No token mint or on-chain liquidity exists for this preview.'}</div><div class="split"><span>Quote asset</span><b>Circle USDC on Solana</b></div><div class="split"><span>Holder rewards</span><b>None</b></div><div class="split"><span>Seed commitment</span><b>${t.seed?money(t.seed)+' USDC · draft only':'Not applicable to sample'}</b></div></div>`;return}if(tab==='liquidity'){$('#activityContent').innerHTML='<div class="about-content"><h3>Buy. Pair. Add. Lock.</h3><p>The proposed engine allocates 0.75% of fee-assessed trade value to this token’s own liquidity strategy. Raydium fees are additional.</p><div class="engine-stages"><span>01<br><b>Accumulate USDC</b></span><span>02<br><b>Buy + pair</b></span><span>03<br><b>Add + lock LP</b></span></div><div class="info-box">No executions yet. Fee collection, buybacks and LP locking are not deployed. Real receipts will appear here when the on-chain integration is live.</div></div>';return}const data=MarketDemo.series(t.id,15,12);$('#activityContent').innerHTML=`<div class="table-scroll"><table><thead><tr><th>Time · UTC</th><th>Side</th><th>Value · USDC</th><th>Price · USDC</th><th>Source</th></tr></thead><tbody>${data.reverse().slice(0,8).map(d=>`<tr><td>${new Date(d.time).toISOString().slice(11,19)}</td><td class="${d.close>=d.open?'positive':'negative'}">${d.close>=d.open?'BUY':'SELL'}</td><td>${money(d.volume)}</td><td>${d.close.toFixed(7)}</td><td><span class="demo-tag">SIMULATED</span></td></tr>`).join('')}</tbody></table></div>`}
